const root=document.querySelector('#app');let token=localStorage.token||'',me=JSON.parse(localStorage.user||'null'),current=null,attempt=null,answers={},examClock=null,finishing=false,justSubmitted=null;
const api=async(path,opts={})=>{let r=await fetch(path,{...opts,headers:{'Content-Type':'application/json',...(token?{Authorization:`Bearer ${token}`}:{})}});let d=await r.json();if(!r.ok)throw Object.assign(Error(d.error||'Xatolik yuz berdi'),{code:d.code,status:r.status,requiredFeature:d.requiredFeature,requiredFeatureLabel:d.requiredFeatureLabel,requiredPlan:d.requiredPlan,requiredPlanLabel:d.requiredPlanLabel});return d};
const go=path=>{history.pushState({},'',path);render()};document.addEventListener('click',e=>{let a=e.target.closest('[data-go]');if(a){e.preventDefault();go(a.dataset.go)}});window.onpopstate=render;
document.addEventListener('click',e=>{const b=e.target.closest('[data-vip-lock]');if(b){e.preventDefault();showVipGate(b.dataset.vipLock||'SILVER',{note:b.dataset.vipNote||undefined})}});
const toast=m=>{let t=document.querySelector('#toast');t.textContent=m;t.className='toast show';setTimeout(()=>t.className='toast',2800)};
const logo=`<div class="brand"><span class="mark">✦</span> CEFR MASTER</div>`;
const nav=()=>`<nav class="nav">${logo}<div class="links"><a data-go="/">Bosh sahifa</a><a data-go="/multilevel">Multi-Level</a><a data-go="/listening">Listening</a><a data-go="/reading">Reading</a><a data-go="/writing">Writing</a><a data-go="/speaking">Speaking</a><a data-go="/vip">💎 VIP</a></div>${me?`<button class="btn light" data-go="/dashboard">Kabinet</button>`:`<button class="btn light" data-go="/login">Kirish</button><button class="btn" data-go="/register">Ro'yxatdan o'tish</button>`}</nav>`;
function home(){root.innerHTML=`${nav()}<main><section class="hero"><div><span class="eyebrow">CEFR MASTER • SMART EXAM PLATFORM</span><h1>CEFR Multi-Level imtihoniga tayyorlaning</h1><p>Listening, Reading, Writing va Speaking bo‘yicha real imtihon formatiga yaqin testlarni bajaring va natijalaringizni kuzating.</p><div class="actions"><button class="btn" data-go="/multilevel">Testlarni ko‘rish</button><button class="btn outline" data-go="/exam/ml-01">Bepul testni boshlash</button></div></div><div class="preview"><div class="screen"><div class="screen-top"><b>CEFR MASTER</b><span>Secure test engine</span></div><h3 style="margin-top:18px">Tizim imkoniyatlari</h3><div class="score-row"><div class="mini-score">Autosave<b>ON</b></div><div class="mini-score">Timer<b>LIVE</b></div><div class="mini-score">Natija<b style="color:#6756e9">CEFR</b></div></div><div class="chart"><i class="bar" style="height:40%"></i><i class="bar" style="height:63%"></i><i class="bar" style="height:53%"></i><i class="bar" style="height:80%"></i><i class="bar" style="height:74%"></i></div></div></div></section><section class="statband"><div class="stats"><div class="stat"><b id="statUsers">—</b><span>Ro‘yxatdan o‘tgan o‘quvchilar</span></div><div class="stat"><b id="statAttempts">—</b><span>Yakunlangan testlar</span></div><div class="stat"><b id="statTests">—</b><span>Mavjud testlar</span></div><div class="stat"><b id="statCerts">—</b><span>Yaratilgan sertifikatlar</span></div></div></section><section class="section"><div class="section-head"><div><span class="eyebrow">IMTIHON MODULLARI</span><h2>Har bir ko‘nikmani mustahkamlang</h2></div></div><div class="grid">${[['🎧','Listening','Audio materiallar bilan ishlang','Listening testlari','/listening'],['📖','Reading','Matnlarni tushunish va tahlil qiling','Reading testlari','/reading'],['✍️','Writing','Yozma ishlaringizni ekspertga yuboring','Writing tasklari','/writing'],['🎙️','Speaking','Ovozingizni yozib, baho oling','Speaking tasklari','/speaking']].map(x=>`<article class="card"><div class="module-icon">${x[0]}</div><h3>${x[1]}</h3><p>${x[2]}</p><div class="meta">${x[3]}</div><button class="btn light" data-go="${x[4]}">Boshlash</button></article>`).join('')}</div></section><section class="section feature"><div class="section-head"><div><span class="eyebrow">MULTI-LEVEL</span><h2>To‘liq sinov imtihonlari</h2><p>O‘z darajangizni haqiqiy imtihon tajribasi orqali biling.</p></div><button class="btn outline" data-go="/multilevel">Barchasi</button></div><div id="mocks" class="grid mock-grid"></div></section><section class="section"><div class="feature-grid">${[['◉','Real format','Vaqt, bo‘limlar va savollar imtihon tartibida.'],['↗','O‘sishni kuzating','Barcha urinishlaringiz bo‘yicha aniq statistika.'],['✓','Ekspert bahosi','Writing va Speaking ishlari malakali tekshiruvdan o‘tadi.']].map(x=>`<div class="feature-item"><span>${x[0]}</span><h3>${x[1]}</h3><p>${x[2]}</p></div>`).join('')}</div></section></main><footer class="footer">${logo}<div><b>CEFR MASTER</b><p>Bilimingizni sinang. Natijangizni biling.</p></div><div><p>Yordam markazi · FAQ · Maxfiylik siyosati</p><p>© 2026 CEFR MASTER</p></div></footer>`;loadMocks();api('/api/public/stats').then(s=>{document.querySelector('#statUsers').textContent=s.users;document.querySelector('#statAttempts').textContent=s.completed;document.querySelector('#statTests').textContent=s.tests;document.querySelector('#statCerts').textContent=s.certificates}).catch(()=>{})}
async function loadMocks(){try{let {tests}=await api('/api/tests');let el=document.querySelector('#mocks');if(el)el.innerHTML=tests.filter(t=>t.category==='multilevel').map((t,i)=>`<article class="card mock"><span class="tag">${t.access==='free'?'BEPUL':t.price.toLocaleString()+' so‘m'}</span><h3>${t.title}</h3><p>${t.modules.map(m=>m[0].toUpperCase()+m.slice(1)).join(' · ')}</p><div class="progress"><i style="width:${i?0:65}%"></i></div><small>${i?'Hali boshlanmagan':'65% bajarilgan'}</small><div class="actions"><button class="btn" data-go="/exam/${t.id}">${i?'Boshlash':'Davom ettirish'}</button></div></article>`).join('')}catch{}}
function auth(kind){let reg=kind==='register',adminLogin=kind==='admin';root.innerHTML=`<div class="auth-wrap"><section class="auth-side">${logo}<h1>${adminLogin?'Xavfsiz boshqaruv markazi':'Bilimingizni sinang. Natijangizni biling.'}</h1><p>${adminLogin?'Bu sahifa faqat ruxsat berilgan administrator va examiner hisoblari uchun.':'CEFR MASTER bilan har bir qadamni kuzating, natijalarni tahlil qiling va maqsadingizga yaqinlashing.'}</p></section><section class="auth-panel"><form class="form" id="auth"><div class="brand">${reg?'Hisob yarating':adminLogin?'Admin portal':'Xush kelibsiz'}</div><h2>${reg?'Ro‘yxatdan o‘tish':adminLogin?'Admin tizimiga kirish':'Tizimga kirish'}</h2><p>${reg?'Bugunoq bepul tayyorgarlikni boshlang.':adminLogin?'Administrator hisob ma’lumotlaringizni kiriting.':'Hisobingizga kirib, tayyorgarlikni davom ettiring.'}</p>${reg?`<div class="field"><label>To‘liq ism</label><input name="name" required placeholder="Ism Familiya"></div><div class="field"><label>Viloyat</label><select name="region"><option>Toshkent</option><option>Samarqand</option><option>Farg‘ona</option><option>Boshqa</option></select></div><div class="field"><label>Telefon</label><input name="phone" placeholder="+998 90 000 00 00"></div>`:''}<div class="field"><label>${reg?'Email':'Email yoki telefon'}</label><input name="${reg?'email':'identifier'}" required placeholder="name@example.com"></div><div class="field"><label>Parol</label><input name="password" type="password" minlength="8" required placeholder="••••••••"></div>${reg?`<div class="field"><label>Parolni tasdiqlang</label><input name="confirm" type="password" required placeholder="••••••••"></div>`:`<p class="small"><span class="link" data-go="/forgot-password">Parolni unutdingizmi?</span></p>`}<button class="btn">${reg?'Ro‘yxatdan o‘tish':'Kirish'}</button>${!adminLogin?`<p class="small" style="text-align:center;margin-top:19px">${reg?'Hisobingiz bormi?':'Hisobingiz yo‘qmi?'} <span class="link" data-go="/${reg?'login':'register'}">${reg?'Kirish':'Ro‘yxatdan o‘tish'}</span></p>`:''}${!reg?'<p class="small">Demo: student@cefrmaster.uz / Student@2026<br>Admin: admin@cefrmaster.uz / Admin@2026</p>':''}</form></section></div>`;document.querySelector('#auth').onsubmit=async e=>{e.preventDefault();let b=Object.fromEntries(new FormData(e.target));if(reg&&b.password!==b.confirm)return toast('Parollar bir xil emas');try{let d=await api(`/api/auth/${reg?'register':adminLogin?'admin-login':'login'}`,{method:'POST',body:JSON.stringify(b)});token=d.token;me=d.user;localStorage.token=token;localStorage.user=JSON.stringify(me);toast('Muvaffaqiyatli');go(me.role==='admin'?'/admin':'/dashboard')}catch(x){toast(x.message)}}}
const studentMenu=()=>{const items=[['/dashboard','Dashboard'],['/tests','Mening testlarim'],['/multilevel','Multi-Level'],['/listening','Listening'],['/reading','Reading'],['/writing','Writing'],['/speaking','Speaking'],['/results','Natijalar'],['/certificates','Sertifikatlar'],['/vip','💎 VIP a‘zolik'],['/profile','Profil']];return `<aside class="side">${logo}<nav class="menu">${items.map(([path,label])=>`<a class="${location.pathname===path?'active':''}" data-go="${path}">${label}</a>`).join('')}<a data-action="logout">Chiqish</a></nav></aside>`;};
async function dashboard(){if(!me)return go('/login');let d=await api('/api/dashboard');root.innerHTML=`<div class="app-shell">${studentMenu()}<main class="app-main"><div class="topline"><div><h1>Assalomu alaykum, ${me.name.split(' ')[0]}! 👋</h1><p>Bu ko‘rsatkichlar hisobingizdagi haqiqiy urinishlardan olinadi.</p></div><div class="userpill">${me.name}${vipBadge(me.membership)}</div></div><section class="kpis"><div class="kpi"><span>Davom etayotgan testlar</span><b>${d.started}</b></div><div class="kpi"><span>Yakunlangan testlar</span><b>${d.completed}</b></div><div class="kpi"><span>O‘rtacha natija</span><b>${d.average}%</b></div><div class="kpi"><span>Eng yuqori natija</span><b>${d.best}%</b></div></section><section class="columns"><div class="table-card"><h3>So‘nggi harakatlar</h3>${d.recent.length?d.recent.map(a=>`<div class="list-row"><div><b>${a.test.title}</b><span>${a.status==='in_progress'?'Javoblar saqlanmoqda':'Yakunlangan'} · ${new Date(a.updatedAt||a.completedAt).toLocaleString('uz-UZ')}</span></div><div>${a.status==='in_progress'?`<button class="btn light" data-go="/exam/${a.test.id}">Davom etish</button>`:a.pendingReview?'<span class="tag">Baholash kutilmoqda</span>':`<b>${a.score}%</b>`}</div></div>`).join(''):`<p class="small">Hali urinishlar yo‘q. Birinchi testingizni boshlang.</p>`}<button class="btn light" style="margin-top:16px" data-go="/multilevel">Testlar katalogi</button></div><div class="table-card"><h3>Natija holati</h3><p class="small">Natijalar avtomatik ballash va examiner bahosidan so‘ng yangilanadi.</p><div class="list-row"><span>Joriy CEFR ko‘rsatkichi</span><b>${d.best>=90?'C2':d.best>=75?'C1':d.best>=60?'B2':d.best>=45?'B1':d.best>=25?'A2':'A1'}</b></div><div class="list-row"><span>Ko‘rib chiqilayotgan ishlar</span><b>${d.recent.filter(x=>x.pendingReview).length}</b></div></div></section></main></div>`}
async function testList(category){root.innerHTML=`${nav()}<section class="section"><div class="section-head"><div><span class="eyebrow">CEFR MASTER</span><h1>${category==='multilevel'?'Multi-Level Mock Tests':category[0].toUpperCase()+category.slice(1)+' testlari'}</h1><p>Test ochilganda urinish yaratiladi va barcha javoblar serverda saqlanadi.</p></div></div><div class="grid mock-grid" id="testlist">Yuklanmoqda...</div></section>`;let {tests}=await api('/api/tests'),history=me?await api('/api/dashboard'):null;let selected=category==='multilevel'?tests.filter(x=>x.category==='multilevel'):tests.filter(x=>x.category===category||x.category==='multilevel');document.querySelector('#testlist').innerHTML=selected.map(t=>{let a=history?.recent.find(x=>x.testId===t.id),locked=!!t.locked;return `<article class="card mock"><span class="tag">${locked?'🔒 Premium':a?.status==='completed'?'✓ Yakunlangan':a?'▶ Jarayonda':'Mavjud'}</span><h3>${t.title}</h3><p>${t.description}</p><p class="small">${t.modules.join(' · ')} · ${t.duration} daqiqa</p><div class="progress"><i style="width:${a?.status==='completed'?100:0}%"></i></div><small>${locked?`${t.price.toLocaleString()} so‘m`:a?.status==='completed'?`${a.score??a.objectiveScore}%`:a?'Saqlangan javoblar bilan davom eting':'Hali boshlanmagan'}</small><div class="actions"><button class="btn ${locked?'outline':''}" ${locked?'disabled':''} data-go="/exam/${t.id}">${locked?'Yopiq':a?.status==='in_progress'?'Davom ettirish':a?.status==='completed'?'Natijani ko‘rish':'Boshlash'}</button></div></article>`}).join('')||'<p>Hozircha testlar topilmadi.</p>'}
async function exam(testId){if(!me)return go('/login');try{clearInterval(examClock);finishing=false;window.__submitting=false;let {test,questions}=await api('/api/tests/'+testId),r=await api('/api/attempts',{method:'POST',body:JSON.stringify({testId})});attempt=r.attempt;answers=Object.fromEntries(r.answers.map(a=>[a.questionId,a.answer]));let index=0,started=new Date(attempt.startedAt).getTime();const save=async(q,val)=>{answers[q.id]=val;await api(`/api/attempts/${attempt.id}/answer`,{method:'POST',body:JSON.stringify({questionId:q.id,answer:val})})};const paint=()=>{let q=questions[index],saved=answers[q.id]??'',spoken=saved&&typeof saved==='object';root.innerHTML=`<div class="exam"><header class="exam-top">${logo}<b>${test.title}</b><span class="timer" id="timer">--:--</span><button class="btn danger finish-top" id="finish">Testni yakunlash</button></header><div class="exam-body"><aside class="q-nav"><b>Test navigatsiyasi</b><div class="q-grid">${questions.map((x,i)=>`<button class="${i===index?'selected':''}" data-q="${i}">${i+1}</button>`).join('')}</div><p class="small">${Object.keys(answers).length}/${questions.length} javob saqlangan</p></aside><main class="question"><span class="eyebrow">${q.module.toUpperCase()} · ${q.type==='writing'?'WRITING TASK':q.type==='speaking'?'SPEAKING TASK':'PART '+(index+1)}</span><h2 style="margin-top:12px">${q.text}</h2>${q.passage?`<div class="passage">${q.passage}</div>`:''}${q.audioText?`<div class="passage listening-material-block">🎧 <b>Listening material</b><span class="small">${q.audioText}</span></div>`:''}${q.type==='single'?`<div>${q.options.map((o,i)=>`<label class="option ${saved!==''&&Number(saved)===i?'checked':''}"><input type="radio" name="answer" value="${i}" ${saved!==''&&Number(saved)===i?'checked':''}> <span>${String.fromCharCode(65+i)}. ${o}</span></label>`).join('')}</div>`:q.type==='speaking'?`<div class="passage"><b>Ovozli javob</b><p class="small">Ovoz yozuvi brauzerdan bevosita serverga yuklanadi. Maksimal hajm: 10 MB.</p>${spoken?`<audio controls src="/uploads/${saved.fileName}" style="width:100%"></audio><p class="small">Yozuv saqlangan. Xohlasangiz, uni yangisiga almashtiring.</p>`:''}<button class="btn outline" id="record">● Yozishni boshlash</button><button class="btn hidden" id="stop">■ To‘xtatish va saqlash</button><span id="recordStatus" class="small"></span></div>`:`<div class="field"><label>Javobingiz</label><textarea id="written" rows="12" placeholder="Javobingizni bu yerga yozing...">${typeof saved==='string'?saved:''}</textarea><p class="small">So‘zlar: <span id="words">0</span> · Belgilar: <span id="chars">0</span> · Javob avtomatik saqlanadi</p></div>`}<div class="exam-actions"><button class="btn outline" id="prev" ${index===0?'disabled':''}>← Oldingi</button><div><button class="btn light" id="flag">⚑ Belgilash</button></div><button class="btn outline" id="next" ${index===questions.length-1?'disabled':''}>Keyingi →</button></div></main></div></div>`;document.querySelectorAll('[data-q]').forEach(b=>b.onclick=()=>{index=+b.dataset.q;paint()});document.querySelectorAll('input[name=answer]').forEach(x=>x.onchange=()=>{document.querySelectorAll('.option').forEach(el=>el.classList.remove('checked'));x.closest('.option').classList.add('checked');save(q,x.value).catch(e=>toast(e.message))});let text=document.querySelector('#written');if(text){let debounce;text.oninput=()=>{let v=text.value.trim();document.querySelector('#words').textContent=v?v.split(/\s+/).length:0;document.querySelector('#chars').textContent=text.value.length;clearTimeout(debounce);debounce=setTimeout(()=>save(q,text.value).then(()=>toast('Draft saqlandi')).catch(e=>toast(e.message)),700)};text.dispatchEvent(new Event('input'))}document.querySelector('#prev').onclick=()=>{index--;paint()};document.querySelector('#next').onclick=()=>{index++;paint()};document.querySelector('#flag').onclick=()=>toast('Savol belgilandi');document.querySelector('#finish').onclick=finish;const recBtn=document.querySelector('#record'),stopBtn=document.querySelector('#stop');if(recBtn)recBtn.onclick=async()=>{if(!navigator.mediaDevices||!window.MediaRecorder)return toast('Bu brauzer audio yozishni qo‘llamaydi');try{let stream=await navigator.mediaDevices.getUserMedia({audio:true}),chunks=[],rec=new MediaRecorder(stream),startedAt=Date.now();rec.ondataavailable=e=>chunks.push(e.data);rec.onstop=async()=>{stream.getTracks().forEach(t=>t.stop());let blob=new Blob(chunks,{type:rec.mimeType}),reader=new FileReader();reader.onload=async()=>{try{const status=document.querySelector('#recordStatus');status.textContent='Yuklanmoqda...';status.className='small upload-status';let out=await api(`/api/attempts/${attempt.id}/audio`,{method:'POST',body:JSON.stringify({questionId:q.id,mime:blob.type,data:String(reader.result).split(',')[1],duration:Math.round((Date.now()-startedAt)/1000)})});answers[q.id]={fileName:out.audio.url.split('/').pop(),duration:out.audio.duration};paint()}catch(e){toast(e.message)}};reader.readAsDataURL(blob)};rec.start();recBtn.classList.add('hidden');stopBtn.classList.remove('hidden');document.querySelector('#recordStatus').textContent='Yozuv tayyorlanmoqda...';stopBtn.onclick=()=>{rec.stop();stopBtn.disabled=true;document.querySelector('#recordStatus').textContent='Yuklanmoqda...'}}catch(e){toast('Mikrofonga ruxsat bering')}};};paint();clearInterval(examClock);examClock=setInterval(()=>{let t=document.querySelector('#timer');if(t){let remaining=Math.max(0,test.duration*60-Math.floor((Date.now()-started)/1000));t.textContent=`${String(Math.floor(remaining/60)).padStart(2,'0')}:${String(remaining%60).padStart(2,'0')}`;if(!remaining){clearInterval(examClock);finish()}}},1000)}catch(e){if(e.code==='MEMBERSHIP_REQUIRED')return renderVipGatePage(e.requiredPlan,{note:e.requiredFeatureLabel?`"${e.requiredFeatureLabel}" uchun ${e.requiredPlanLabel||'VIP'} yoki undan yuqori tarif kerak.`:undefined});toast(e.message);go(e.code==='SUBMISSION_PENDING'?'/results':'/multilevel')}}
function setSubmitting(on){window.__submitting=on;document.querySelectorAll('#finish,#yes,#no').forEach(b=>b.disabled=on);const y=document.querySelector('#yes');if(y)y.innerHTML=on?'<span class="spinner"></span> Yuborilmoqda...':'Ha, yakunlash'}
async function finish(){if(finishing||document.querySelector('#confirm'))return;const unanswered=Object.values(answers).filter(value=>value!==undefined&&value!==null&&value!=='').length;const remaining=Math.max(0,(window.currentQuestionTotal||0)-unanswered);root.insertAdjacentHTML('beforeend',`<div class="modal" id="confirm"><div><h2>Testni yakunlaysizmi?</h2><p>Siz hali ${remaining} ta savolga javob bermadingiz. Haqiqatan ham testni yakunlamoqchimisiz?</p><div class="actions"><button class="btn outline" id="no">Yo‘q</button><button class="btn danger" id="yes">Ha, yakunlash</button></div></div></div>`);document.querySelector('#no').onclick=()=>{if(!finishing)document.querySelector('#confirm')?.remove()};document.querySelector('#yes').onclick=async()=>{if(finishing)return;finishing=true;setSubmitting(true);try{const r=await api(`/api/attempts/${attempt.id}/finish`,{method:'POST'});clearInterval(examClock);justSubmitted=r.submission||{};toast('Test muvaffaqiyatli topshirildi');go('/results')}catch(e){finishing=false;setSubmitting(false);toast(e.message);if(e.code==='EMPTY_ATTEMPT')document.querySelector('#confirm')?.remove()}}}
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const statusPill=s=>`<span class="status-pill st-${s.status}">${esc(s.statusLabel)}</span>`;
const MLMODS=[['listening','Listening'],['reading','Reading'],['writing','Writing'],['speaking','Speaking']];
const fmtDate=v=>v?new Date(v).toLocaleString('uz-UZ'):'—';
const mlCard=r=>`<article class="ml-result ml-${esc(r.status)}" data-submission="${esc(r.id)}"><div class="ml-head"><div><span class="eyebrow">MULTILEVEL</span><h4>${esc(r.testTitle)}</h4></div></div><div class="ml-status"><span class="ml-label">Status</span>${statusPill(r)}</div>${r.status==='ready'&&r.score!==null?`<div class="ml-score"><div class="ml-big"><span class="ml-label">Overall Score</span><b>${r.score}</b></div><div class="ml-big"><span class="ml-label">Level</span><b class="${r.level?'':'ml-nolevel'}">${esc(r.levelLabel||'—')}</b></div></div><div class="ml-mods">${MLMODS.map(([k,l])=>`<div><span class="ml-label">${l}</span><b>${r.modules&&typeof r.modules[k]==='number'?r.modules[k]:'—'}</b></div>`).join('')}</div>`:''}<div class="ml-foot"><div><span class="ml-label">Date</span><b>${fmtDate(r.submittedAt)}</b></div>${r.checkedAt?`<div><span class="ml-label">Checked</span><b>${fmtDate(r.checkedAt)}</b></div>`:''}</div>${r.demoCertificate?`<div class="ml-cert"><div class="ml-cert-info"><b>Demo sertifikat</b><span class="small">DEMO — UNOFFICIAL · motivatsion namuna, rasmiy hujjat emas</span></div><div class="ml-cert-actions"><button class="btn" type="button" data-cert-view="${esc(r.id)}">VIEW DEMO CERTIFICATE</button><button class="btn light" type="button" data-cert-download="${esc(r.id)}">DOWNLOAD DEMO CERTIFICATE</button></div></div>`:''}</article>`;
const resSig=d=>JSON.stringify((d.submissions||[]).map(x=>[x.id,x.status,x.score,x.level,x.checkedAt]));
function pollResults(d){clearTimeout(window.__resTimer);if(!(d.submissions||[]).some(x=>x.status!=='ready'))return;const sig=resSig(d),tick=async()=>{if(location.pathname!=='/results')return;if(!document.hidden){try{const n=await api('/api/submissions');if(location.pathname==='/results'&&resSig(n)!==sig)return results()}catch(e){}}window.__resTimer=setTimeout(tick,8000)};window.__resTimer=setTimeout(tick,8000)}
