async function questionBuilder(testId){let {tests}=await api('/api/tests'),test=tests.find(t=>t.id===testId),{questions}=await api(`/api/admin/tests/${testId}/questions`);if(!test)return go('/admin/tests');root.innerHTML=`<div class="app-shell"><aside class="side">${logo}<nav class="menu"><a data-go="/admin">Dashboard</a><a data-go="/admin/tests">← Testlar</a><a class="active">Savol builder</a></nav></aside><main class="app-main"><div class="topline"><div><span class="eyebrow">QUESTION BUILDER</span><h1>${test.title}</h1><p>${questions.length} ta savol · ${test.modules.join(', ')}</p></div></div><section class="columns"><div class="table-card"><h3>Savollar</h3>${questions.length?questions.map((q,i)=>`<div class="list-row"><div><b>${i+1}. ${q.text}</b><span>${q.module} · ${q.type} · ${q.points} ball</span></div><button class="btn outline" data-delete-q="${q.id}">O‘chirish</button></div>`).join(''):'<p class="small">Hali savollar yo‘q.</p>'}</div><form class="table-card" id="questionForm"><h3>Yangi savol qo‘shish</h3><div class="field"><label>Modul</label><select name="module">${test.modules.map(m=>`<option>${m}</option>`).join('')}</select></div><div class="field"><label>Savol turi</label><select name="type" id="qtype"><option value="single">Multiple choice</option><option value="writing">Writing task</option><option value="speaking">Speaking task</option><option value="text">Text input</option></select></div><div class="field"><label>Savol matni</label><textarea name="text" required rows="4"></textarea></div><div class="field"><label>Variantlar (har qatorga bittadan, MCQ uchun)</label><textarea name="options" rows="4"></textarea></div><div class="field"><label>To‘g‘ri variant raqami (0 dan boshlab)</label><input name="correct" type="number" value="0"></div><div class="field"><label>Ball</label><input name="points" type="number" value="1" min="1"></div><button class="btn">Savolni saqlash</button></form></section></main></div>`;document.querySelector('#questionForm').onsubmit=async e=>{e.preventDefault();let b=Object.fromEntries(new FormData(e.target));b.options=b.options.split('\n').map(x=>x.trim()).filter(Boolean);try{await api(`/api/admin/tests/${testId}/questions`,{method:'POST',body:JSON.stringify(b)});toast('Savol saqlandi');questionBuilder(testId)}catch(x){toast(x.message)}};document.querySelectorAll('[data-delete-q]').forEach(b=>b.onclick=async()=>{if(confirm('Savol o‘chirilsinmi?')){await api('/api/admin/questions/'+b.dataset.deleteQ,{method:'DELETE'});questionBuilder(testId)}})}
let reviewFilter={};
const SUB_CATS=[['','Barchasi'],['multilevel','Multilevel'],['speaking','Speaking'],['listening','Listening'],['writing','Writing'],['reading','Reading']];
const shortId=v=>esc(String(v||'').length>14?String(v).slice(0,12)+'…':v);
const adminNav=()=>`<aside class="side">${logo}<nav class="menu"><a data-go="/admin">Dashboard</a><a data-go="/admin/users">Foydalanuvchilar</a><a data-go="/admin/tests">Testlar</a><a class="active" data-go="/admin/reviews">Topshirilgan testlar</a><a data-go="/admin/vip">💎 VIP boshqaruvi</a></nav></aside>`;
const CHK_FIELDS=[['listening','Listening'],['reading','Reading'],['writing','Writing'],['speaking','Speaking'],['overall','Overall Score']];
const cefrOf=(score,rules)=>{const v=Math.floor(score),r=(rules||[]).find(x=>v>=x.min&&(x.max===null||v<=x.max));return r?r.level:null};
const fmtDay=v=>{const d=new Date(v||Date.now());return String(d.getDate()).padStart(2,'0')+'.'+String(d.getMonth()+1).padStart(2,'0')+'.'+d.getFullYear()};
const readScore=(input,int)=>{const raw=String(input.value).trim();if(input.validity.badInput||raw==='')return {error:raw===''&&!input.validity.badInput?'Ball kiritilishi shart':'Faqat son kiriting'};if(!/^\d+([.,]\d+)?$/.test(raw))return {error:'Faqat musbat son kiriting'};if(int&&!/^\d+$/.test(raw))return {error:'Overall Score butun son bo‘lishi kerak'};const n=Number(raw.replace(',','.'));return n>100?{error:'Ball 100 dan oshmasligi kerak'}:{value:n}};
async function reviewPage(id){
  if(!me||!['admin','super_admin','examiner'].includes(me.role))return go('/admin/login');
  root.innerHTML=`<div class="app-shell">${adminNav()}<main class="app-main"><div class="skeleton-card"></div></main></div>`;
  let det;try{det=await api(`/api/admin/submissions/${encodeURIComponent(id)}/open`,{method:'POST'})}catch(e){toast(e.message);return go('/admin/reviews')}
  drawReviewPage(det);
}
function drawReviewPage(det,saved){
  const sub=det.submission,c=det.candidate,res=det.result,sg=det.suggested||{},rules=det.levelRules,none=det.levelNone||'Level not assigned';
  const init={};CHK_FIELDS.forEach(([k])=>init[k]=res?res[k]:sg[k]);
  const certCode=sub.certificate?.code;
  root.innerHTML=`<div class="app-shell">${adminNav()}<main class="app-main"><div class="topline"><div><span class="link" data-go="/admin/reviews">← Topshirilgan testlar</span><h1>Multilevel tekshirish</h1><p>${esc(sub.testTitle)} · Submission <code title="${esc(sub.id)}">${esc(sub.id)}</code></p></div><div>${statusPill(sub)}</div></div>${saved?`<div class="success-banner" role="status"><b>✓ Natija saqlandi.</b> Status: <b>${esc(sub.statusLabel)}</b> · CEFR Level: <b>${esc(sub.levelLabel||'—')}</b>. Submission ID o‘zgarmadi.</div>`:''}<div class="chk-grid"><section class="chk-left"><div class="table-card chk-card"><span class="eyebrow">NOMZOD MA’LUMOTLARI</span><p class="small">Ma’lumotlar foydalanuvchi hisobidan avtomatik olindi.</p><dl class="chk-dl"><div><dt>Familyasi | Surname</dt><dd>${esc(c.surname||'—')}</dd></div><div><dt>Ismi | First Name</dt><dd>${esc(c.firstName||'—')}</dd></div><div><dt>Chet tili | Foreign Language</dt><dd>${esc(c.foreignLanguage)}</dd></div><div><dt>Berilgan sanasi | Date of issue</dt><dd>${fmtDay(c.issueDate)}</dd></div></dl><p class="small chk-meta">Hisob: ${esc(c.email)}<br>Topshirilgan: ${new Date(sub.submittedAt).toLocaleString('uz-UZ')}<br>Tekshirilgan sana | Checking date: ${fmtDay(c.checkDate)}</p></div><div class="table-card chk-card"><span class="eyebrow">SERTIFIKAT NAMUNASI</span><div class="cert-preview ${sub.status==='ready'?'':'is-draft'}"><div class="cert-brand">CEFR MASTER</div><div class="cert-title">MULTILEVEL CERTIFICATE</div><div class="cert-name">${esc([c.firstName,c.surname].filter(Boolean).join(' '))}</div><div class="cert-row"><span>Surname</span><b>${esc(c.surname||'—')}</b></div><div class="cert-row"><span>First name</span><b>${esc(c.firstName||'—')}</b></div><div class="cert-row"><span>Foreign language</span><b>English</b></div><div class="cert-scores">${CHK_FIELDS.map(([k,l])=>`<div class="${k==='overall'?'cert-overall':''}"><span>${l}</span><b data-pv="${k}">—</b></div>`).join('')}<div><span>Level</span><b data-pv="level">—</b></div></div><div class="cert-foot"><span>Date of issue: <b>${fmtDay(c.issueDate)}</b></span><span>${certCode?'No: <b>'+esc(certCode)+'</b>':'Raqam saqlangandan so‘ng beriladi'}</span></div>${sub.status==='ready'?'':'<div class="cert-mark">NAMUNA</div>'}</div></div><div class="table-card chk-card"><span class="eyebrow">TOPSHIRILGAN JAVOBLAR</span>${det.tasks.length?det.tasks.map(t=>`<details class="chk-answer"><summary>${esc(t.question.module)} · ${t.question.type==='writing'?'WRITING':'SPEAKING'}</summary><div class="passage">${esc(t.question.text)}</div>${t.question.type==='writing'?`<div class="passage answer-text">${esc(t.answer)}</div>`:t.answer&&t.answer.fileName?`<audio controls src="/uploads/${encodeURIComponent(t.answer.fileName)}" style="width:100%"></audio>`:'<p class="small">Audio yo‘q</p>'}</details>`).join(''):'<p class="small">Yozma yoki og‘zaki javob topshirilmagan.</p>'}</div></section><aside class="chk-right"><form class="table-card chk-card" id="chkForm" novalidate><div class="chk-top"><span class="eyebrow">TEKSHIRISH FORMASI</span></div><p class="small">Har bir ball 0–100 oralig‘ida bo‘lishi kerak. Avtomatik hisoblangan qiymatlar taklif sifatida qo‘yilgan, ularni o‘zgartirishingiz mumkin.</p>${CHK_FIELDS.map(([k,l])=>`<div class="field chk-field${k==='overall'?' chk-overall':''}"><label for="chk-${k}">${l}</label><input id="chk-${k}" name="${k}" type="number" min="0" max="100" step="${k==='overall'?'1':'any'}" inputmode="${k==='overall'?'numeric':'decimal'}" autocomplete="off" value="${init[k]===null||init[k]===undefined?'':esc(init[k])}">${k==='overall'?'':`<small class="chk-hint">${typeof sg[k]==='number'?'Avto: '+sg[k]:'Avto: baholanmagan'}</small>`}<small class="chk-err" data-err="${k}"></small></div>`).join('')}<button class="btn light" type="button" id="chkAvg">O‘rtachani hisoblash</button><div class="field chk-cefr"><label>CEFR Level</label><div class="chk-cefr-value" id="chkLevel" data-pv="level" aria-live="polite">—</div><small class="chk-hint">Avtomatik hisoblanadi: 40–49 B1 · 50–60 B2 · 61+ C1 · 40 dan past: ${esc(none)}</small></div><div class="actions chk-actions"><button class="btn outline" type="button" data-go="/admin/reviews">Orqaga</button><button class="btn" type="submit" id="chkSave">SAVE RESULT</button></div></form></aside></div></main></div>`;
  const form=root.querySelector('#chkForm'),inputs=Object.fromEntries(CHK_FIELDS.map(([k])=>[k,form.elements[k]]));
  let dirtyOverall=!!res;
  const paint=()=>{CHK_FIELDS.forEach(([k])=>{const r=readScore(inputs[k]);root.querySelectorAll(`[data-pv="${k}"]`).forEach(e=>e.textContent=r.value!==undefined?r.value:'—')});const o=readScore(inputs.overall,true),lv=o.value!==undefined?(cefrOf(o.value,rules)||none):'—';root.querySelectorAll('[data-pv="level"]').forEach(e=>{e.textContent=lv;e.classList.toggle('is-none',lv===none)})};
  const avg=()=>{const v=['listening','reading','writing','speaking'].map(k=>readScore(inputs[k]).value);return v.every(x=>x!==undefined)?Math.round(v.reduce((p,q)=>p+q,0)/4):null};
  const validate=show=>{let ok=true;CHK_FIELDS.forEach(([k])=>{const r=readScore(inputs[k],k==='overall'),e=form.querySelector(`[data-err="${k}"]`);if(r.error)ok=false;if(show){e.textContent=r.error||'';inputs[k].classList.toggle('is-invalid',!!r.error)}});return ok};
  ['listening','reading','writing','speaking'].forEach(k=>inputs[k].addEventListener('input',()=>{if(!dirtyOverall){const m=avg();if(m!==null)inputs.overall.value=m}paint();validate(true)}));
  inputs.overall.addEventListener('input',()=>{dirtyOverall=true;paint();validate(true)});
  form.querySelector('#chkAvg').onclick=()=>{const m=avg();if(m===null){toast('Avval to‘rttala modul ballini ham kiriting');return}inputs.overall.value=m;dirtyOverall=false;paint();validate(true)};
  paint();
  form.onsubmit=async e=>{e.preventDefault();if(!validate(true)){toast('Ballarni tekshiring');return}const btn=form.querySelector('#chkSave');if(btn.disabled)return;btn.disabled=true;try{const body=Object.fromEntries(CHK_FIELDS.map(([k])=>[k,String(inputs[k].value).trim()]));const out=await api(`/api/admin/submissions/${encodeURIComponent(sub.id)}/result`,{method:'POST',body:JSON.stringify(body)});toast('Natija saqlandi · Natija tayyor');drawReviewPage(out,true);window.scrollTo(0,0)}catch(x){btn.disabled=false;if(x.message)toast(x.message)}};
}
async function reviews(filter=reviewFilter){reviewFilter=filter;const qs=new URLSearchParams(Object.entries(filter).filter(([,v])=>v)).toString();let d=await api('/api/admin/submissions'+(qs?'?'+qs:'')),subs=d.submissions;root.innerHTML=`<div class="app-shell"><aside class="side">${logo}<nav class="menu"><a data-go="/admin">Dashboard</a><a data-go="/admin/users">Foydalanuvchilar</a><a data-go="/admin/tests">Testlar</a><a class="active" data-go="/admin/reviews">Topshirilgan testlar</a><a data-go="/admin/vip">💎 VIP boshqaruvi</a></nav></aside><main class="app-main"><div class="topline"><div><h1>Topshirilgan testlar</h1><p>Har bir topshirilgan test bu ro‘yxatda faqat bir marta ko‘rinadi.</p></div></div><section class="kpis sub-kpis"><div class="kpi"><span>Jami topshiriq</span><b>${d.counts.total}</b></div><div class="kpi"><span>Admin javobi kutilmoqda</span><b>${d.counts.pending_admin}</b></div><div class="kpi"><span>Tekshirilmoqda</span><b>${d.counts.in_review}</b></div><div class="kpi"><span>Natija tayyor</span><b>${d.counts.ready}</b></div></section><div class="table-card" style="margin-top:18px"><div class="sub-filters">${SUB_CATS.map(([v,l])=>`<button class="${(filter.category||'')===v?'active':''}" data-fcat="${v}">${l}</button>`).join('')}<select id="fstatus" aria-label="Holat bo‘yicha filtr"><option value="">Barcha holatlar</option>${Object.entries(d.labels).map(([v,l])=>`<option value="${v}" ${filter.status===v?'selected':''}>${esc(l)}</option>`).join('')}</select></div>${subs.length?`<div class="sub-table-wrap"><table class="sub-table"><thead><tr><th>Submission ID</th><th>User ID</th><th>Foydalanuvchi</th><th>Test turi</th><th>Sana</th><th>Holat</th><th>Umumiy ball</th><th></th></tr></thead><tbody>${subs.map(s=>`<tr><td><code title="${esc(s.id)}">${shortId(s.id)}</code></td><td><code title="${esc(s.userId)}">${shortId(s.userId)}</code></td><td><b>${esc(s.userName)}</b></td><td>${esc(s.categoryLabel)}<br><span class="small">${esc(s.testTitle)}</span></td><td>${new Date(s.submittedAt).toLocaleString('uz-UZ')}</td><td>${statusPill(s)}${s.pendingTasks?`<br><span class="small">${s.pendingTasks} ta topshiriq kutmoqda</span>`:''}</td><td>${s.score!==null?`<b>${s.score}%</b> · ${esc(s.levelLabel||'')}`:'—'}</td><td><button class="btn ${s.status==='ready'?'light':''}" data-open="${esc(s.id)}" data-cat="${esc(s.category)}">TEKSHIRISH</button></td></tr>`).join('')}</tbody></table></div>`:'<p class="small">Bu filtr bo‘yicha topshiriqlar yo‘q.</p>'}</div></main></div>`;document.querySelectorAll('[data-fcat]').forEach(b=>b.onclick=()=>reviews({...reviewFilter,category:b.dataset.fcat}));document.querySelector('#fstatus').onchange=e=>reviews({...reviewFilter,status:e.target.value});document.querySelectorAll('[data-open]').forEach(b=>b.onclick=async()=>{if(b.dataset.cat==='multilevel')return go('/admin/reviews/'+encodeURIComponent(b.dataset.open));b.disabled=true;try{openSubmission(await api(`/api/admin/submissions/${b.dataset.open}/open`,{method:'POST'}))}catch(e){b.disabled=false;toast(e.message)}})}
const finalizeBlock=sub=>{const ms=Object.entries(sub.moduleScores||{}).map(([m,s])=>`${esc(m)}: ${s===null?'kutilmoqda':s}`).join(' · ');return sub.status==='ready'?`<p class="small review-final"><b>Natija tayyor.</b> Overall: ${sub.score} · ${esc(sub.levelLabel||'')}. Foydalanuvchiga ko‘rsatilmoqda.</p>`:`<div class="review-final"><p class="small">${ms?'Hisoblangan ballar: '+ms+'<br>':''}Natijani saqlaganingizdan so‘ng foydalanuvchi Overall Score, Level va modul ballarini ko‘radi.</p><button class="btn" type="button" id="finalizeBtn" ${sub.pendingTasks>0?'disabled':''}>Natijani saqlash</button>${sub.pendingTasks>0?`<span class="small"> ${sub.pendingTasks} ta topshiriq hali baholanmagan</span>`:''}</div>`};
function openSubmission(det){const sub=det.submission,old=document.querySelector('#reviewModal'),scroll=old?old.firstElementChild.scrollTop:0;old?.remove();const rub=['Task achievement / Fluency','Coherence / Vocabulary','Lexical resource / Grammar','Grammar / Pronunciation'];root.insertAdjacentHTML('beforeend',`<div class="modal" id="reviewModal"><div class="review-modal"><div class="review-head"><div><span class="eyebrow">${esc(sub.categoryLabel)} · ${esc(sub.id)}</span><h2>${esc(sub.testTitle)}</h2><p class="small"><b>${esc(det.student?.name||sub.userName)}</b> · ${esc(det.student?.email||'')} · ${new Date(sub.submittedAt).toLocaleString('uz-UZ')}</p></div><div>${statusPill(sub)}${sub.score!==null?`<div class="review-score"><b>${sub.score}%</b> · ${esc(sub.levelLabel||'')}</div>`:''}</div></div>${det.tasks.length?det.tasks.map((t,i)=>{const ev=t.evaluation,r=ev?.rubric||{};return `<section class="review-task"><span class="eyebrow">${esc(t.question.module)} · ${t.question.type==='writing'?'WRITING':'SPEAKING'} ${ev?'<span class="status-pill st-ready">Baholangan</span>':'<span class="status-pill st-pending_admin">Kutilmoqda</span>'}</span><div class="passage">${esc(t.question.text)}</div>${t.question.type==='writing'?`<div class="passage answer-text">${esc(t.answer)}</div>`:t.answer&&t.answer.fileName?`<audio controls src="/uploads/${encodeURIComponent(t.answer.fileName)}" style="width:100%"></audio>`:''}<form data-task="${i}"><div class="rubric-grid">${rub.map((x,k)=>`<div class="field"><label>${x} (0–100)</label><input name="r${k}" type="number" min="0" max="100" required value="${esc(r['criterion'+(k+1)]??'')}"></div>`).join('')}</div><div class="field"><label>Umumiy ball (0–100)</label><input name="overall" type="number" min="0" max="100" required value="${esc(ev?.overall??'')}"></div><div class="field"><label>Examiner fikri</label><textarea name="feedback" rows="3" required>${esc(ev?.feedback||'')}</textarea></div><div class="actions"><button class="btn" type="submit">${ev?'Bahoni yangilash':'Baholashni saqlash'}</button></div></form></section>`}).join(''):`<p class="small review-none">Qo‘lda tekshiriladigan yozma yoki og‘zaki topshiriq yo‘q. Natija avtomatik hisoblangan.${Object.keys(sub.moduleScores||{}).length?'<br>'+Object.entries(sub.moduleScores).map(([m,s])=>`${esc(m)}: ${s===null?'kutilmoqda':s+'%'}`).join(' · '):''}</p>`}${sub.category==='multilevel'?finalizeBlock(sub):''}<div class="actions"><button class="btn outline" type="button" id="closeReview">Yopish</button></div></div></div>`);const modal=document.querySelector('#reviewModal');modal.firstElementChild.scrollTop=scroll;const close=()=>{modal.remove();reviews()};modal.querySelector('#closeReview').onclick=close;const fb=modal.querySelector('#finalizeBtn');if(fb)fb.onclick=async()=>{fb.disabled=true;try{const out=await api(`/api/admin/submissions/${sub.id}/finalize`,{method:'POST'});toast('Natija saqlandi · Natija tayyor');openSubmission(out)}catch(x){fb.disabled=false;toast(x.message)}};modal.addEventListener('mousedown',e=>{if(e.target===modal)close()});modal.querySelectorAll('form[data-task]').forEach(f=>f.onsubmit=async e=>{e.preventDefault();const btn=f.querySelector('button[type=submit]');if(btn.disabled)return;btn.disabled=true;const b=Object.fromEntries(new FormData(f)),t=det.tasks[+f.dataset.task];try{const out=await api('/api/admin/evaluations',{method:'POST',body:JSON.stringify({attemptId:det.attempt.id,questionId:t.question.id,overall:b.overall,feedback:b.feedback,rubric:{criterion1:b.r0,criterion2:b.r1,criterion3:b.r2,criterion4:b.r3}})});toast(out.submission&&out.submission.status==='ready'?'Baho saqlandi · Natija tayyor':'Baho saqlandi');openSubmission(await api(`/api/admin/submissions/${sub.id}`))}catch(x){btn.disabled=false;toast(x.message)}})}
async function adminSettings(){let {settings}=await api('/api/admin/settings'),t=settings.thresholds;root.innerHTML=`<div class="app-shell"><aside class="side">${logo}<nav class="menu"><a data-go="/admin">Dashboard</a><a data-go="/admin/tests">Testlar</a><a data-go="/admin/vip">💎 VIP boshqaruvi</a><a class="active" data-go="/admin/settings">Sozlamalar</a></nav></aside><main class="app-main"><div class="topline"><div><h1>Platforma sozlamalari</h1><p>CEFR daraja chegaralari natija hisoblashda server tomonidan ishlatiladi.</p></div></div><form class="table-card" id="settingsForm"><div class="field"><label>Platforma nomi</label><input name="siteName" value="${settings.siteName}"></div><h3>CEFR chegaralari (%)</h3><div class="grid" style="grid-template-columns:repeat(3,1fr)">${Object.entries(t).map(([k,v])=>`<div class="field"><label>${k}</label><input name="${k}" type="number" min="0" max="100" value="${v}"></div>`).join('')}</div><button class="btn">Sozlamalarni saqlash</button></form></main></div>`;document.querySelector('#settingsForm').onsubmit=async e=>{e.preventDefault();let v=Object.fromEntries(new FormData(e.target));let thresholds={};Object.keys(t).forEach(k=>thresholds[k]=Number(v[k]));await api('/api/admin/settings',{method:'PUT',body:JSON.stringify({siteName:v.siteName,thresholds})});toast('Sozlamalar saqlandi')}}
async function certificates(){if(!me)return go('/login');let {certificates}=await api('/api/certificates');root.innerHTML=`<div class="app-shell">${studentMenu()}<main class="app-main"><div class="topline"><div><h1>Sertifikatlar</h1><p>Faqat to‘liq baholangan yakuniy natijalar uchun yaratiladi.</p></div></div><div class="table-card">${certificates.length?certificates.map(c=>`<div class="list-row"><div><b>${c.attempt.test.title}</b><span>${c.code} · ${new Date(c.issuedAt).toLocaleDateString('uz-UZ')}</span></div><div><b>${c.attempt.score}% · ${esc(c.attempt.levelLabel||c.attempt.level)}</b> <button class="btn light" data-go="/certificate/${c.code}">Tekshirish</button></div></div>`).join(''):'<p class="small">Hozircha sertifikat yo‘q. Writing/Speaking baholari yakunlangach sertifikat avtomatik yaratiladi.</p>'}</div></main></div>`}
async function certificate(code){try{let r=await api('/api/certificate/'+code);root.innerHTML=`${nav()}<section class="section" style="max-width:800px"><div class="table-card" style="text-align:center;padding:55px"><div class="mark" style="margin:auto">✓</div><p class="eyebrow" style="margin-top:17px">SERTIFIKAT TASDIQLANDI</p><h1 style="margin:12px 0">Certificate of Achievement</h1><p>Ushbu sertifikat CEFR MASTER tizimida haqiqiy natija asosida yaratilgan.</p><div class="passage" style="text-align:left;margin-top:30px"><div class="list-row"><span>O‘quvchi</span><b>${r.certificate.student}</b></div><div class="list-row"><span>Imtihon</span><b>${r.certificate.exam}</b></div><div class="list-row"><span>Natija</span><b>${r.certificate.score}% · ${esc(r.certificate.levelLabel||r.certificate.level)}</b></div><div class="list-row"><span>Sertifikat ID</span><b>${r.certificate.code}</b></div></div></div></section>`}catch(e){root.innerHTML=`${nav()}<section class="section"><div class="table-card"><h1>Sertifikat topilmadi</h1><p>${e.message}</p></div></section>`}}
async function profile(){let d=await api('/api/dashboard'),mem=await api('/api/me').then(r=>{me=r.user;localStorage.user=JSON.stringify(me);return r.user.membership}).catch(()=>me&&me.membership);root.innerHTML=`<div class="app-shell">${studentMenu()}<main class="app-main"><div class="topline"><div><h1>Mening profilim</h1><p>Profil ma’lumotlari serverga saqlanadi.</p></div></div><div class="columns"><form class="table-card" id="profileForm"><div class="module-icon" style="font-size:20px">${me.name[0]}</div><h2 style="margin-top:15px">Profil ma’lumotlari${vipBadge(mem)}</h2><div class="field"><label>To‘liq ism</label><input name="name" value="${me.name}" required></div><div class="field"><label>Email</label><input value="${me.email}" disabled></div><div class="field"><label>Telefon</label><input name="phone" value="${me.phone||''}"></div><div class="field"><label>Viloyat</label><input name="region" value="${me.region||''}"></div><button class="btn">O‘zgarishlarni saqlash</button></form><section class="table-card">${membershipCard(mem)}<h3>Haqiqiy statistika</h3><div class="list-row"><span>Yakunlangan testlar</span><b>${d.completed}</b></div><div class="list-row"><span>O‘rtacha natija</span><b>${d.average}%</b></div><div class="list-row"><span>Eng yuqori natija</span><b>${d.best}%</b></div><hr style="border:0;border-top:1px solid #e8ebf5;margin:20px 0"><h3>Parolni almashtirish</h3><form id="passwordForm"><div class="field"><label>Joriy parol</label><input name="currentPassword" type="password" required></div><div class="field"><label>Yangi parol</label><input name="newPassword" type="password" minlength="8" required></div><button class="btn outline">Parolni yangilash</button></form></section></section></main></div>`;document.querySelector('#profileForm').onsubmit=async e=>{e.preventDefault();try{let r=await api('/api/me',{method:'PUT',body:JSON.stringify(Object.fromEntries(new FormData(e.target)))});me=r.user;localStorage.user=JSON.stringify(me);toast('Profil saqlandi');profile()}catch(e){toast(e.message)}};document.querySelector('#passwordForm').onsubmit=async e=>{e.preventDefault();try{await api('/api/me/password',{method:'PUT',body:JSON.stringify(Object.fromEntries(new FormData(e.target)))});e.target.reset();toast('Parol yangilandi')}catch(e){toast(e.message)}}}
const moduleInfo={listening:{icon:'🎧',label:'Listening Lab',title:'Eshiting. Anglang. Ishoning.',desc:'Qisqa dialoglar, amaliy e’lonlar va imtihon formatidagi savollar bilan tinglash ko‘nikmangizni charxlang.',note:'Har bir audio bo‘limida javoblaringiz avtomatik saqlanadi.',color:'aqua',steps:['Audio bilan tanishing','Savollarga javob bering','Natijani tahlil qiling']},reading:{icon:'📚',label:'Reading Room',title:'Matn ortidagi ma’noni toping.',desc:'Skan qilish, asosiy fikrni aniqlash va detail savollarni bosqichma-bosqich mashq qiling.',note:'Passage va savollar telefonda ham qulay ikki bosqichli tartibda ishlaydi.',color:'coral',steps:['Passage’ni o‘qing','Dalilni toping','Javobingizni tekshiring']},writing:{icon:'✍️',label:'Writing Workshop',title:'Fikringizni aniq va ishonchli yozing.',desc:'Katta muharrir, jonli so‘zlar sanagichi va examiner feedback yordamida yozma nutqingizni o‘stiring.',note:'Yozgan har bir gapingiz draft sifatida serverga avtomatik saqlanadi.',color:'violet',steps:['Vazifani rejalang','Javobni yozing','Expert bahosini oling']},speaking:{icon:'🎙️',label:'Speaking Studio',title:'Ovozingizga imkon bering.',desc:'Tayyorlaning, mikrofonda yozing va haqiqiy audio topshiriq sifatida yuboring.',note:'Yozuv xavfsiz saqlanadi, examiner uni tinglab baholaydi.',color:'gold',steps:['60 soniya tayyorlaning','Javobingizni yozing','Feedback’ni tinglang']},multilevel:{icon:'✦',label:'Full Mock',title:'To‘liq CEFR sinov tajribasi.',desc:'Barcha to‘rt ko‘nikmani bir testda sinang va umumiy CEFR natijangizni oling.',note:'Timer, autosave va server hisoblagan natija bilan to‘liq imtihon.',color:'navy',steps:['Testni boshlang','Bo‘limlarni yakunlang','Natijani oling']}};
async function testList(category){const key=moduleInfo[category]?' '+category:' multilevel',m=moduleInfo[category]||moduleInfo.multilevel;root.innerHTML=`${nav()}<main class="module-page ${m.color}"><section class="module-hero"><div class="module-copy"><span class="module-kicker">${m.icon} ${m.label}</span><h1>${m.title}</h1><p>${m.desc}</p><div class="module-note">✦ ${m.note}</div></div><aside class="learning-path"><span>BUGUNGI YO‘L</span>${m.steps.map((s,i)=>`<div><b>0${i+1}</b><p>${s}</p></div>`).join('')}</aside></section><section class="section module-content"><div class="section-head"><div><span class="eyebrow">MASHG‘ULOTLAR KATALOGI</span><h2>Siz uchun tayyorlangan testlar</h2><p>Har bir mashg‘ulotda progress alohida saqlanadi.</p></div></div><div class="study-layout"><div class="test-stream" id="testlist"><div class="skeleton-card"></div><div class="skeleton-card"></div></div><aside class="practice-tip"><span>${m.icon}</span><h3>Bugungi maslahat</h3><p>${category==='writing'?'Avval 3–4 ta asosiy g‘oyani rejalashtiring, keyin paragraphlarni yozing.':category==='speaking'?'Yozuvdan oldin 3 ta kalit so‘z yozib oling va tabiiy gapiring.':category==='reading'?'Avval savollarni ko‘ring, keyin matndan kerakli joyni toping.':'Audio boshlanishidan oldin javob variantlarini tez ko‘zdan kechiring.'}</p><button class="btn outline" data-go="/dashboard">Mening progressim</button></aside></div></section></main>`;try{let {tests}=await api('/api/tests'),history=me?await api('/api/dashboard'):null;let selected=tests.filter(x=>x.category===category);if(category==='multilevel')selected=tests.filter(x=>x.category==='multilevel');let el=document.querySelector('#testlist');el.innerHTML=selected.map((t,i)=>{let a=history?.recent.find(x=>x.testId===t.id),locked=!!t.locked;return `<article class="study-test"><div class="test-index">${String(i+1).padStart(2,'0')}</div><div class="test-info"><span>${t.duration} daqiqa · ${t.modules.join(' + ')}</span><h3>${t.title}</h3><p>${t.description}</p><div class="test-status">${locked?'🔒 '+(t.requiredPlanLabel||'Premium')+' kerak':a?.status==='in_progress'?'● Autosave faol':a?.status==='completed'?'✓ Yakunlangan':'○ Boshlashga tayyor'}</div></div><div class="test-action"><span class="difficulty">${t.access==='free'?'BEPUL':!t.locked?'VIP':t.price.toLocaleString()+' so‘m'}</span><button class="btn ${locked?'outline':''}" ${locked?`data-vip-lock="${esc(t.requiredPlan||'SILVER')}" data-vip-note="${esc(t.title)}${t.requiredFeatureLabel?' — '+esc(t.requiredFeatureLabel):''} uchun ${esc(t.requiredPlanLabel||'VIP')} yoki undan yuqori tarif kerak."`:`data-go="/exam/${t.id}"`}>${locked?'🔒 VIP kerak':a?.status==='in_progress'?'Davom ettirish':a?.status==='completed'?'Natija':'Boshlash'} →</button></div></article>`}).join('')||`<div class="empty-state"><span>${m.icon}</span><h3>Yangi mashg‘ulotlar tez orada</h3><p>Admin ushbu modul uchun testlarni qo‘shganda ular shu yerda paydo bo‘ladi.</p></div>`}catch(e){document.querySelector('#testlist').innerHTML=`<p class="small">Katalog yuklanmadi: ${e.message}</p>`}}
function forgotten(){root.innerHTML=`<div class="auth-wrap"><section class="auth-side">${logo}<h1>Parolni qayta tiklash</h1><p>Email yoki telefoningizga yuborilgan tasdiqlash kodi yordamida hisobingizni qayta tiklang.</p></section><section class="auth-panel"><form class="form" onsubmit="event.preventDefault();toast('Tasdiqlash kodi yuborildi')"><h2>Parolni unutdingizmi?</h2><p>Email yoki telefon raqamingizni kiriting.</p><div class="field"><label>Email / Telefon</label><input required placeholder="name@example.com"></div><button class="btn">Kodni yuborish</button><p class="small" style="text-align:center"><span class="link" data-go="/login">Kirish sahifasiga qaytish</span></p></form></section></div>`}
document.addEventListener('click',e=>{if(e.target.closest('[data-action="logout"]')){token='';me=null;localStorage.clear();go('/')}});
function render(){clearInterval(examClock);let p=location.pathname;if(p==='/')return home();if(p==='/login')return auth('login');if(p==='/admin/login')return auth('admin');if(p==='/register')return auth('register');if(p==='/forgot-password')return forgotten();if(p==='/dashboard')return dashboard();if(p==='/profile')return profile();if(p==='/results')return results();if(p==='/certificates')return certificates();if(p==='/vip')return vipPage();if(p==='/multilevel'||['/listening','/reading','/writing','/speaking','/tests'].includes(p))return testList(p==='/tests'?'multilevel':p.slice(1));if(p.startsWith('/exam/'))return exam(p.split('/').pop());if(p.startsWith('/certificate/'))return certificate(p.split('/').pop());if(p==='/admin')return admin();if(p==='/admin/users')return adminUsers();if(p==='/admin/tests')return adminTests();if(p.startsWith('/admin/tests/'))return questionBuilder(p.split('/').pop());if(p.startsWith('/admin/reviews/'))return reviewPage(decodeURIComponent(p.split('/').pop()));if(p==='/admin/reviews')return reviews();if(p==='/admin/settings')return adminSettings();if(p==='/admin/vip')return adminVip();return home()}render();
